443: /**
444:  * After any change to the workspace, verified requirements rest on a verifier run of an older state: they become
445:  * implemented (model-reported) again, with a note. Returns the ids demoted.
446:  */
447: export function invalidateVerified(ledger: ObjectiveLedger, reason: string, at = now()): string[] {
448:   const demoted: string[] = [];
449:   for (const r of ledger.requirements) {
450:     if (r.status !== "verified") continue;
451:     r.status = "implemented";
452:     r.note = clip(`verification invalidated: ${reason}${r.verifiedBy ? ` (was verifier #${r.verifiedBy.attempt})` : ""}`, MAX_EVIDENCE_CHARS);
453:     r.verifiedBy = undefined;
454:     r.updatedAt = at;
455:     demoted.push(r.id);
456:   }
457:   return demoted;
458: }
