460: /** The first line of a failing verifier's output that names the failure; else its last non-empty line. */
461: export function failedCheckFrom(output: string): string | undefined {
462:   const lines = output.split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
463:   // Lines that report a failure first (an echoed command that merely mentions "FAIL" is not one), then any mention.
464:   const reported = lines.find((line) => /^(✖|×|not ok\b|FAIL(ED)?\b|error(\[|:|\b)|thread .* panicked|test result: FAILED|AssertionError)/i.test(line));
465:   const failing = reported ?? lines.find((line) => /(\bFAIL(ED)?\b|\bfailed\b|\berror\[|panicked)/i.test(line) && !/\b0 failed\b/.test(line));
466:   const chosen = failing ?? lines[lines.length - 1];
467:   return chosen ? clip(chosen, MAX_EVIDENCE_CHARS) : undefined;
468: }
