470: /**
471:  * The last real attempt of `command` whose result still applies: same workspace identity, same agent process, no
472:  * mutating tool call since, same ignored-input fingerprint. Anything less certain returns undefined, so the verifier
473:  * runs again — reusing a failure is only an optimisation and must never block a legitimate rerun.
474:  */
475: export function priorAttempt(
476:   ledger: ObjectiveLedger,
477:   command: string,
478:   current: { inputs: string; epoch: string; mutationSeq: number; external: string },
479: ): VerificationAttempt | undefined {
480:   for (let i = ledger.verification.length - 1; i >= 0; i--) {
481:     const attempt = ledger.verification[i];
482:     if (attempt.command !== command || attempt.status === "SKIPPED_UNCHANGED_INPUTS") continue;
483:     const same =
484:       attempt.inputs === current.inputs &&
485:       attempt.epoch === current.epoch &&
486:       attempt.mutationSeq === current.mutationSeq &&
487:       attempt.external === current.external;
488:     return same ? attempt : undefined;
489:   }
490:   return undefined;
491: }
