493: export function recordAttempt(ledger: ObjectiveLedger, attempt: Omit<VerificationAttempt, "n" | "at">, at = now()): VerificationAttempt {
494:   const lastN = ledger.verification.length > 0 ? (ledger.verification[ledger.verification.length - 1]?.n ?? 0) : 0;
495:   const record: VerificationAttempt = { n: lastN + 1, at, ...attempt };
496:   ledger.verification.push(record);
497:   if (ledger.verification.length > 50) ledger.verification = ledger.verification.slice(-50);
498:   return record;
499: }
