      break;
    case "keep_waiting":
      delete this.state.wait;
      u.status = "RUNNABLE";
      break;
    case "assign":
      u.override = { resourceId: action.resourceId, overriding: action.overriding, decisionId };
      u.runsBase = u.runs;
      u.status = "RUNNABLE";
      break;
    case "revise":
      u.prompt = `${u.prompt}${REVISION_MARKER}${text}`;
      u.runsBase = u.runs;
      u.status = "RUNNABLE";
      break;
    case "replace_task":
      // The earlier operator revisions stay: only the base task is replaced.
      u.prompt = `${text}${u.prompt.slice(unitBaseTask(u.prompt).length)}`;
      delete u.context;
      u.runsBase = u.runs;
      u.status = "RUNNABLE";
      break;
    case "set_inputs":
      u.inputs = redactForPersistence({ ...(u.inputs ?? {}), ...suppliedInputs });
      u.runsBase = u.runs;
      u.status = "RUNNABLE";
      break;
    case "lift_context_budget":
      delete u.contextBudget;
      delete u.context;
      u.runsBase = u.runs;
      u.status = "RUNNABLE";
      break;
    case "drop":
      u.dropped = true;
      break;

